1	import type { AuthoredExplanation } from './authoredChartExplanations';
2	
3	export type EducationInviteSettings = { minAnswers:number; maxAnswers:number };
4	type Phrase = { id:string; text:string };
5	type PhraseCycle = { used:Set<string>; last:string|null };
6	
7	const FRAMING: readonly Phrase[] = [
8	  {id:'education-framing-symbol',text:'Let us look at what this symbol means in astrology, starting with the calculated facts.'},
9	  {id:'education-framing-tradition',text:'Here is the traditional meaning of this chart feature and how astrologers arrived at it.'},
10	  {id:'education-framing-language',text:'We can explore the chart’s symbolic language without turning it into a personal prediction.'},
11	  {id:'education-framing-piece',text:'I will explain this piece of the chart on its own, keeping the calculated facts separate from the tradition.'},
12	];
13	const INVITATIONS: readonly Phrase[] = [
14	  {id:'education-invite-connect',text:'If you would like me to connect these pieces into a personal reading, purchase credits through Top Up. We can then explore the connections in the context of the question you choose to bring.'},
15	  {id:'education-invite-thinking',text:'I can explain each symbol here for free. To have me think through the connections in your own chart with you, purchase credits through Top Up for a personal reading.'},
16	  {id:'education-invite-together',text:'When you want a personal reading that puts these pieces together, purchase credits through Top Up. That is where we can consider how the parts connect around your own question.'},
17	  {id:'education-invite-explore',text:'There is more free education to explore whenever you like. If you want me to connect what we have covered into a personal reading, purchase credits through Top Up.'},
18	];
19	
20	export function readEducationInviteSettings(environment: Readonly<Record<string, unknown>>): EducationInviteSettings {
21	  const read = (name:string) => {
22	    const raw=environment[name];
23	    if (typeof raw!=='string' || !/^[2-4]$/.test(raw.trim())) throw new Error(`${name} must be an integer from 2 through 4.`);
24	    return Number(raw.trim());
25	  };
26	  const minAnswers=read('VITE_EDUCATION_INVITE_MIN_ANSWERS');
27	  const maxAnswers=read('VITE_EDUCATION_INVITE_MAX_ANSWERS');
28	  if (minAnswers>maxAnswers) throw new Error('VITE_EDUCATION_INVITE_MAX_ANSWERS must not be less than VITE_EDUCATION_INVITE_MIN_ANSWERS.');
29	  return {minAnswers,maxAnswers};
30	}
31	
32	export type PreparedEducationAnswer = Readonly<{
33	  requestId:string;
34	  answer:AuthoredExplanation;
35	  session:object;
36	  revision:number;
37	  framingId:string;
38	  invitationId:string|null;
39	}>;
40	export interface AuthoredEducationSession {
41	  readonly ownerUid:string;
42	  prepare(requestId:string, lesson:(framing:string)=>AuthoredExplanation):PreparedEducationAnswer|null;
43	  commit(prepared:PreparedEducationAnswer, current:()=>boolean, deliver:(answer:AuthoredExplanation)=>void):boolean;
44	}
45	
46	const choose = <T,>(values:readonly T[]):T => values[Math.floor(Math.random()*values.length)];
47	function pickPhrase(phrases:readonly Phrase[], cycle:PhraseCycle):Phrase {
48	  const unused=phrases.filter(phrase=>!cycle.used.has(phrase.id));
49	  return choose(unused.length ? unused : phrases.filter(phrase=>phrase.id!==cycle.last));
50	}
51	function rememberPhrase(phrases:readonly Phrase[], cycle:PhraseCycle, id:string) {
52	  if (cycle.used.size===phrases.length) cycle.used.clear();
53	  cycle.used.add(id);cycle.last=id;
54	}
55	
56	/** A caller-owned account session. Preparation consumes no count/history; successful text delivery advances it. */
57	export function createAuthoredEducationSession(ownerUid:string, settings:EducationInviteSettings):AuthoredEducationSession {
58	  if (!Number.isInteger(settings.minAnswers) || settings.minAnswers<2 || settings.minAnswers>4) throw new Error('VITE_EDUCATION_INVITE_MIN_ANSWERS must be an integer from 2 through 4.');
59	  if (!Number.isInteger(settings.maxAnswers) || settings.maxAnswers<settings.minAnswers || settings.maxAnswers>4) throw new Error('VITE_EDUCATION_INVITE_MAX_ANSWERS must be an integer from the configured minimum through 4.');
60	  const thresholds=Array.from({length:settings.maxAnswers-settings.minAnswers+1},(_,index)=>settings.minAnswers+index);
61	  const nextThreshold = (previous?:number) => choose(thresholds.length>1 ? thresholds.filter(value=>value!==previous) : thresholds);
62	  const identity={};
63	  const committed=new Set<string>();
64	  const framing:PhraseCycle={used:new Set(),last:null}, invitations:PhraseCycle={used:new Set(),last:null};
65	  let sinceInvitation=0, threshold=nextThreshold(), revision=0;
66	  return {
67	    ownerUid,
68	    prepare(requestId,lesson) {
69	      if (!requestId || committed.has(requestId)) return null;
70	      const phrase=pickPhrase(FRAMING,framing);
71	      const invitation=sinceInvitation+1>=threshold ? pickPhrase(INVITATIONS,invitations) : null;
72	      const explanation=lesson(phrase.text);
73	      return {requestId,session:identity,revision,framingId:phrase.id,invitationId:invitation?.id??null,
74	        answer:{...explanation,targets:[...explanation.targets],text:explanation.text+(invitation ? '\n\n'+invitation.text : '')}};
75	    },
76	    commit(prepared,current,deliver) {
77	      if (prepared.session!==identity || prepared.revision!==revision || committed.has(prepared.requestId) || !current()) return false;
78	      // Delivery is synchronous: a thrown preparation/commit does not consume a count or phrase.
79	      deliver(prepared.answer);
80	      committed.add(prepared.requestId);revision++;sinceInvitation++;
81	      rememberPhrase(FRAMING,framing,prepared.framingId);
82	      if (prepared.invitationId) {
83	        rememberPhrase(INVITATIONS,invitations,prepared.invitationId);
84	        sinceInvitation=0;threshold=nextThreshold(threshold);
85	      }
86	      return true;
87	    },
88	  };
89	}
